def check(output: str, ctx: dict) -> bool:
    if 'distinct' in ctx['question'].lower():
        sql = extract_sql(output).lower()
        return 'distinct' in sql
    return True

def check(output: str, ctx: dict) -> bool:
    question = ctx['question'].lower()
    sql = extract_sql(output).lower()
    keywords = ['where', '!=', '<>', 'not in', 'not like']
    if 'not' in question or 'except' in question:
        return any(keyword in sql for keyword in keywords)
    return True

