def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output)
    columns = [col.lower() for table in ctx['schema'] for col in ctx['schema'][table]]
    return all(word.lower() in columns for word in re.findall(r'\b\w+\b', sql) if word.upper() != word and word.lower() != 'select')
    return True

