def check(output, ctx):
    schema = ctx['schema']
    sql = extract_sql(output).lower()
    for table, columns in schema.items():
        for column in columns:
            if sum(column.lower() in other_columns for other_table, other_columns in schema.items()) > 1 and f'{column.lower()}' in sql and f'{table.lower()}.' not in sql:
                return False
    return True
